export function isUnsupportedCreation(text: string) {
  // Describing work-related distress is not commissioning an artifact.
  if (/^(?:我在|我因为|我正在|我做).*(?:焦虑|难受|压力|沮丧|累)/.test(text) && !/(?:请|帮我|给我|替我|为我)/.test(text)) return false;
